-- Kawasaki Europe 2027 Ninja 500 SE exact variant; do not generalize to all Ninja 500.
with documented(catalog_model_id,category,label,value,start_year,market,source_name,source_url) as (values
(913,'brakes','Ninja 500 SE 2027 Europe front and rear brake discs','{"model_year":2027,"variant":"SE","front_brake_diameter_mm":310,"rear_brake_diameter_mm":220,"front_brake":"Semi-floating single disc","rear_brake":"Single disc"}'::jsonb,2027,'Europe 2027 Ninja 500 SE variant','Kawasaki Motors Europe','https://www.kawasaki.eu/en/Motorcycles/Supersport_Sport/Ninja_500_SE_2027.html'),
