(913,'dimensions','Ninja 500 SE 2027 Europe wheelbase and fuel tank','{"model_year":2027,"variant":"SE","wheelbase_mm":1375,"ground_clearance_mm":145,"fuel_capacity_l":14,"length_mm":1995,"width_mm":730,"height_mm":1120}'::jsonb,2027,'Europe 2027 Ninja 500 SE variant','Kawasaki Motors Europe','https://www.kawasaki.eu/en/Motorcycles/Supersport_Sport/Ninja_500_SE_2027.html'),
(913,'engine','Ninja 500 SE 2027 Europe bore and stroke','{"model_year":2027,"variant":"SE","bore_mm":70,"stroke_mm":58.6,"compression_ratio":"11.3:1","fuel_injection":"Two 32 mm throttle bodies"}'::jsonb,2027,'Europe 2027 Ninja 500 SE variant','Kawasaki Motors Europe','https://www.kawasaki.eu/en/Motorcycles/Supersport_Sport/Ninja_500_SE_2027.html'),
(913,'performance','Ninja 500 SE 2027 Europe output and consumption','{"model_year":2027,"variant":"SE","power_kw":33.4,"power_ps":45,"power_rpm":9000,"torque_nm":42.6,"torque_rpm":6000,"fuel_consumption_l_per_100km":3.8,"co2_g_per_km":89}'::jsonb,2027,'Europe 2027 Ninja 500 SE variant','Kawasaki Motors Europe','https://www.kawasaki.eu/en/Motorcycles/Supersport_Sport/Ninja_500_SE_2027.html'),
(913,'chassis','Ninja 500 SE 2027 Europe geometry and rear suspension','{"model_year":2027,"variant":"SE","frame":"High-tensile steel trellis","rake_degrees":24.5,"trail_mm":92,"rear_suspension":"Bottom-link Uni-Trak gas-charged shock, preload adjustable"}'::jsonb,2027,'Europe 2027 Ninja 500 SE variant','Kawasaki Motors Europe','https://www.kawasaki.eu/en/Motorcycles/Supersport_Sport/Ninja_500_SE_2027.html'),
(913,'transmission','Ninja 500 SE 2027 Europe gearing and chain','{"model_year":2027,"variant":"SE","gearbox":"Six-speed return shift","clutch":"Wet multi-disc","final_drive":"Sealed chain"}'::jsonb,2027,'Europe 2027 Ninja 500 SE variant','Kawasaki Motors Europe','https://www.kawasaki.eu/en/Motorcycles/Supersport_Sport/Ninja_500_SE_2027.html'),
(913,'design','Ninja 500 SE 2027 Europe front face and fairing','{"model_year":2027,"variant":"SE","headlights":"Twin compact headlights","front_design":"Twin forward-projecting spoilers","bodywork":"Layered full fairing"}'::jsonb,2027,'Europe 2027 Ninja 500 SE variant','Kawasaki Motors Europe','https://www.kawasaki.eu/en/Motorcycles/Supersport_Sport/Ninja_500_SE_2027.html'),
(913,'specification','Ninja 500 SE 2027 Europe TFT connectivity and KIPASS','{"model_year":2027,"variant":"SE","instrument":"TFT with smartphone connectivity","key_system":"KIPASS proximity activation system"}'::jsonb,2027,'Europe 2027 Ninja 500 SE variant','Kawasaki Motors Europe','https://www.kawasaki.eu/en/Motorcycles/Supersport_Sport/Ninja_500_SE_2027.html'),
(913,'factory_colours','Ninja 500 SE 2027 Europe colours','{"model_year":2027,"variant":"SE","factory_colours":["Lime Green","Metallic Matte Graphenesteel Gray / Metallic Spark Black"]}'::jsonb,2027,'Europe 2027 Ninja 500 SE variant','Kawasaki Motors Europe','https://www.kawasaki.eu/en/Motorcycles/Supersport_Sport/Ninja_500_SE_2027.html')
), added as (
insert into public.motorcycle_catalog_facts(catalog_model_id,category,label,value,start_year,market,source_name,source_url,verification_status)
select d.catalog_model_id,d.category,d.label,d.value,d.start_year,d.market,d.source_name,d.source_url,'verified'
from documented d join public.motorcycle_catalog_models m on m.id=d.catalog_model_id and m.manufacturer='Kawasaki' and m.model='Ninja 500'
where not exists(select 1 from public.motorcycle_catalog_facts f where f.catalog_model_id=d.catalog_model_id and f.label=d.label)
returning id,source_url
)
insert into public.motorcycle_catalog_fact_verification_audit(fact_id,checked_at,verification_basis,source_url,scope_note,source_version)
select id,now(),'manufacturer_primary_source_individual_model_checked_2026_11_12',source_url,
'2027 Kawasaki Ninja 500 SE Europe variant-specific official specifications; not every year or standard trim.',
'Kawasaki Europe Ninja 500 SE 2027 product page' from added;
